// Ice shader
// Kind of poor attempt at combining lighting, fresnel & refractions for icy effect
// By veik
// DMC January 2025 entry to the Solid Water theme (not very creative hehe)

#define N_ITERS 4

// Using stefan gustavsons cellular noise:

// Cellular noise ("Worley noise") in 2D in GLSL.
// Copyright (c) Stefan Gustavson 2011-04-19. All rights reserved.
// This code is released under the conditions of the MIT license.
// See LICENSE file for details.
// https://github.com/stegu/webgl-noise

// Modulo 289 without a division (only multiplications)
vec3 mod289(vec3 x) {
  return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec2 mod289(vec2 x) {
  return x - floor(x * (1.0 / 289.0)) * 289.0;
}

// Modulo 7 without a division
vec3 mod7(vec3 x) {
  return x - floor(x * (1.0 / 7.0)) * 7.0;
}

// Permutation polynomial: (34x^2 + 10x) mod 289
vec3 permute(vec3 x) {
  return mod289((34.0 * x + 10.0) * x);
}

// Cellular noise, returning F1 and F2 in a vec2.
// Standard 3x3 search window for good F1 and F2 values
vec2 cellular(vec2 P) {
#define K 0.142857142857 // 1/7
#define Ko 0.428571428571 // 3/7
#define jitter 1.0 // Less gives more regular pattern
	vec2 Pi = mod289(floor(P));
 	vec2 Pf = fract(P);
	vec3 oi = vec3(-1.0, 0.0, 1.0);
	vec3 of = vec3(-0.5, 0.5, 1.5);
	vec3 px = permute(Pi.x + oi);
	vec3 p = permute(px.x + Pi.y + oi); // p11, p12, p13
	vec3 ox = fract(p*K) - Ko;
	vec3 oy = mod7(floor(p*K))*K - Ko;
	vec3 dx = Pf.x + 0.5 + jitter*ox;
	vec3 dy = Pf.y - of + jitter*oy;
	vec3 d1 = dx * dx + dy * dy; // d11, d12 and d13, squared
	p = permute(px.y + Pi.y + oi); // p21, p22, p23
	ox = fract(p*K) - Ko;
	oy = mod7(floor(p*K))*K - Ko;
	dx = Pf.x - 0.5 + jitter*ox;
	dy = Pf.y - of + jitter*oy;
	vec3 d2 = dx * dx + dy * dy; // d21, d22 and d23, squared
	p = permute(px.z + Pi.y + oi); // p31, p32, p33
	ox = fract(p*K) - Ko;
	oy = mod7(floor(p*K))*K - Ko;
	dx = Pf.x - 1.5 + jitter*ox;
	dy = Pf.y - of + jitter*oy;
	vec3 d3 = dx * dx + dy * dy; // d31, d32 and d33, squared
	// Sort out the two smallest distances (F1, F2)
	vec3 d1a = min(d1, d2);
	d2 = max(d1, d2); // Swap to keep candidates for F2
	d2 = min(d2, d3); // neither F1 nor F2 are now in d3
	d1 = min(d1a, d2); // F1 is now in d1
	d2 = max(d1a, d2); // Swap to keep candidates for F2
	d1.xy = (d1.x < d1.y) ? d1.xy : d1.yx; // Swap if smaller
	d1.xz = (d1.x < d1.z) ? d1.xz : d1.zx; // F1 is in d1.x
	d1.yz = min(d1.yz, d2.yz); // F2 is now not in d2.yz
	d1.y = min(d1.y, d1.z); // nor in  d1.z
	d1.y = min(d1.y, d2.x); // F2 is in d1.y, we're done.
	return sqrt(d1.xy);
}// END

// My code:


vec2 fbm(vec2 st) {
    float gain = 1.0;
    float norm = 0.0;
    vec2 v = vec2(0.0);

    for (int i = 0; i < N_ITERS; i++) {
        v += gain * cellular(st);
        st += 123.123;
        norm += gain;
        gain /= 2.6;
        st *= 2.0;
    }

    return v / norm;
}

float height(vec2 xy) {
    xy /= 2.0;
    xy += 0.9 * fbm(xy.yx - 321.321);
    float v = fbm(xy).y * 2.0 - 1.0;
    return 1.0 - pow(v, 3.0);
}

vec4 terrain(vec2 xy) {
    const vec2 eps = vec2(0.005, 0.0);
    float h0 = height(xy + eps.xy); // Height
    return vec4(
        h0 - height(xy - eps.xy),
        eps.x,
        height(xy + eps.yx) - height(xy - eps.yx),
        1.0-clamp(0.0, 1.0, h0)
    );
}


void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 st0 = (fragCoord.xy/iResolution.y) * 2.0;
    st0.y -= 1.0;
    st0.x -= iResolution.x/iResolution.y;

    float camH = 1.0 + sin(iTime * 0.3) * 0.5;

    vec2 st = 1.5*st0;
    st *= camH;
    st.y += iTime * 0.6;


    vec3 V = normalize(vec3(st0.x, 1.0, st0.y));
    vec4 layer = terrain(st); // xyz is normal, a is height
    layer.y *= 2.0;
    vec3 N = normalize(layer.xyz);
    vec3 R = normalize(reflect(-V, N));

    vec3 color = vec3(0.0);

    // Main light
    float v = 0.0;
    vec3 L = normalize(vec3(0.0, 0.1, 0.0));
    vec3 Lcolor = vec3(0.8, 0.9, 1.0);

    float NdotV = max(0.0, dot(N, V));
    float NdotL = max(0.0, dot(N, L));
    float RdotL = max(0.0, dot(R, L));

    // diffuse factor
    float fresnelN = min(1.0, pow(1.0 - NdotV, 1.2) * 0.5 + 0.4);
    v += NdotL * fresnelN;

    // specular factor
    v += 1.0 * pow(RdotL, 20.0);

    color += Lcolor * v;

    // Refraction
    vec3 Rf = normalize(refract(V, N, 1.0 / 1.309));

    // More ice: darker
    vec3 iceColor = mix(vec3(0.1, 0.15, 0.2), vec3(0.03, 0.04, 0.1), pow(1.0 - Rf.y, 0.3));

    // Pattern behind ice
    vec2 floorSt = st + Rf.xz / abs(Rf.y);
    float floorColor = step(0.9, fract(4.0 * floorSt.x)) + step(0.9, fract(4.0 * floorSt.y));
    iceColor += vec3( floorColor * 0.2 / (1.0 + length(Rf.xz) * 2.0) );

    color = 0.3 * iceColor + color;

    // Lets say, when angle is high, lots of air bubbles so ice reflects light everywhere...
    color = mix(color, vec3(0.9, 0.95, 1.0), pow(1.0 - N.y, 0.7));

    color = pow(color, vec3(2.0));

    fragColor.xyz = color;
}
